CREATE DEFINER=`root`@`localhost` PROCEDURE `GetLastWeekMissingTimesheetReport` (IN `p_StaffUserId` INT)   BEGIN
    DECLARE v_role_name VARCHAR(50);
    DECLARE done INT DEFAULT 0;
    DECLARE current_staff INT;

    -- 1. Get role
    SELECT r.role INTO v_role_name
    FROM staffs s
    JOIN roles r ON s.role_id = r.id
    WHERE s.id = p_StaffUserId
    LIMIT 1;

    -- 2. Temporary table for queue (simulate JS queue)
    CREATE TEMPORARY TABLE tmp_queue (
        staff_id INT PRIMARY KEY
    );
    TRUNCATE TABLE tmp_queue;

    -- 3. Temporary table for all collected staff IDs
    CREATE TEMPORARY TABLE tmp_all_staffs (
        staff_id INT PRIMARY KEY
    );
    TRUNCATE TABLE tmp_all_staffs;

    -- Insert initial staff into both tables

    -- 4. Iterative loop simulating JS queue
    WHILE EXISTS (SELECT 1 FROM tmp_queue) DO
        -- Take one staff from queue
        SELECT staff_id INTO current_staff FROM tmp_queue LIMIT 1;

        -- Delete it from queue
        DELETE FROM tmp_queue WHERE staff_id = current_staff;

        -- Insert subordinates who are not already in all_staffs
        SELECT staff_to
        FROM line_managers
        WHERE staff_by = current_staff
        AND staff_to NOT IN (SELECT staff_id FROM tmp_all_staffs);

        -- Insert the same new staff into all_staffs
        SELECT staff_to
        FROM line_managers
        WHERE staff_by = current_staff;
    END WHILE;

    -- 5. Build WHERE clause
    SET @where_clause = '';
    IF v_role_name IN ('SUPERADMIN', 'ADMIN', 'MANAGEMENT') THEN
        SET @where_clause = "ts.submit_status = '0' OR ts.submit_status IS NULL";
    ELSE
        SET @where_clause = "(ts.submit_status = '0' OR ts.submit_status IS NULL) AND st.id IN (SELECT staff_id FROM tmp_all_staffs)";
    END IF;

    -- 6. Final dynamic SQL
    SET @sql = CONCAT("
        SELECT 
            CONCAT(st.first_name, ' ', st.last_name) AS staff_fullname,
            st.email AS staff_email,
            st.id AS staff_id,
            COALESCE(ts.submit_status, 0) AS submit_status,
            COALESCE(
                DATE_FORMAT(ts.monday_date, '%Y-%m-%d'),
                DATE_FORMAT(ts.tuesday_date, '%Y-%m-%d'),
                DATE_FORMAT(ts.wednesday_date, '%Y-%m-%d'),
                DATE_FORMAT(ts.thursday_date, '%Y-%m-%d'),
                DATE_FORMAT(ts.friday_date, '%Y-%m-%d'),
                DATE_FORMAT(ts.saturday_date, '%Y-%m-%d'),
                DATE_FORMAT(ts.sunday_date, '%Y-%m-%d')
            ) AS week_date
        FROM staffs st
        LEFT JOIN timesheet ts 
            ON st.id = ts.staff_id
            AND YEARWEEK(
                COALESCE(
                    ts.monday_date,
                    ts.tuesday_date,
                    ts.wednesday_date,
                    ts.thursday_date,
                    ts.friday_date,
                    ts.saturday_date,
                    ts.sunday_date
                ), 1
            ) = YEARWEEK(CURDATE() - INTERVAL 1 WEEK, 1)
        WHERE ", @where_clause, "
        GROUP BY st.id, st.first_name, st.last_name, st.email, ts.submit_status, week_date
        ORDER BY st.first_name ASC
    ");

    -- 7. Execute
    PREPARE stmt FROM @sql;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;

    -- 8. Cleanup
    DROP TEMPORARY TABLE IF EXISTS tmp_queue;
    DROP TEMPORARY TABLE IF EXISTS tmp_all_staffs;

END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `get_assigned_jobs_staff` (IN `p_staff_id` INT)   BEGIN
    SELECT  
        customers.id, clients.id, jobs.id, staffs.id,
        'assign_customer_portfolio', NULL
    FROM customers
    JOIN staff_portfolio ON staff_portfolio.customer_id = customers.id
    JOIN staffs ON staffs.id = staff_portfolio.staff_id
    LEFT JOIN clients ON clients.customer_id = customers.id
    LEFT JOIN jobs ON jobs.client_id = clients.id
    WHERE staffs.id = p_staff_id

    UNION ALL

    SELECT  
        customers.id, clients.id, jobs.id, staffs.id,
        'assign_customer_service', customer_services.service_id
    FROM customers
    JOIN customer_services ON customer_services.customer_id = customers.id
    JOIN customer_service_account_managers 
        ON customer_service_account_managers.customer_service_id = customer_services.id
    JOIN staffs ON staffs.id = customer_service_account_managers.account_manager_id
    LEFT JOIN clients ON clients.customer_id = customers.id
    LEFT JOIN jobs ON jobs.client_id = clients.id
    WHERE staffs.id = p_staff_id

    UNION ALL

    SELECT  
        customers.id, clients.id, jobs.id, staffs.id,
        'assign_customer_main_account_manager', NULL
    FROM customers
    JOIN staffs ON staffs.id = customers.account_manager_id
    LEFT JOIN clients ON clients.customer_id = customers.id
    LEFT JOIN jobs ON jobs.client_id = clients.id
    WHERE staffs.id = p_staff_id

    UNION ALL

    SELECT  
        customers.id, clients.id, jobs.id, jobs.reviewer,
        'reviewer', NULL
    FROM jobs
    JOIN clients ON clients.id = jobs.client_id
    JOIN customers ON customers.id = clients.customer_id
    JOIN staffs ON staffs.id = jobs.reviewer
    WHERE jobs.reviewer = p_staff_id

    UNION ALL

    SELECT  
        customers.id, clients.id, jobs.id, jobs.allocated_to,
        'allocated_to', NULL
    FROM jobs
    JOIN clients ON clients.id = jobs.client_id
    JOIN customers ON customers.id = clients.customer_id
    JOIN staffs ON staffs.id = jobs.allocated_to
    WHERE jobs.allocated_to = p_staff_id

    UNION ALL

    SELECT  
        customers.id, clients.id, jobs.id, job_allowed_staffs.staff_id,
        'job_allowed_staffs', NULL
    FROM jobs
    JOIN clients ON clients.id = jobs.client_id
    JOIN customers ON customers.id = clients.customer_id
    LEFT JOIN job_allowed_staffs ON job_allowed_staffs.job_id = jobs.id
    JOIN staffs ON staffs.id = job_allowed_staffs.staff_id
    WHERE job_allowed_staffs.staff_id = p_staff_id;
END$$

DELIMITER ;

